#!/bin/bash
# Prueba previa (sin desplegar): copia de /opt/faceops con memo de CVE por equipo y de arquitecturas; mide la gráfica en producción. Sin secretos.
sudo podman exec faceops bash -c 'rm -rf /tmp/fo3114 && cp -r /opt/faceops /tmp/fo3114'
echo  | base64 -d > /tmp/cves3114.py; echo  | base64 -d > /tmp/arq3114.py
sudo podman cp /tmp/cves3114.py faceops:/tmp/fo3114/app/cves.py; sudo podman cp /tmp/arq3114.py faceops:/tmp/fo3114/app/arquitectura.py
cat > /tmp/p3114.py <<'PY'
import time
from app import create_app
app = create_app()
with app.test_client() as c:
    with c.session_transaction() as s: s["uid"] = 1; s["csrf"] = "x"
    for amb in ("produccion", "qa", "produccion"):
        qs = {"vista": "negocio", "nivel": "segmento", "valor": "App de pagos", "ambiente": amb}
        ts = []
        for i in range(3):
            t0 = time.time(); r = c.get("/lab/mapa/datos", query_string=qs); ts.append(f"{time.time()-t0:.2f}s[{r.status_code}]")
        t0 = time.time(); r2 = c.get("/lab/mapa", query_string={"vista": "aplicaciones", "segmento": "App de pagos", "ambiente": amb})
        print(amb, "grafica", " ".join(ts), "· pagina", f"{time.time()-t0:.2f}s[{r2.status_code}]")
PY
sudo podman cp /tmp/p3114.py faceops:/tmp/p3114.py
echo "== antes (código desplegado)"; sudo podman exec -w /opt/faceops -e PYTHONPATH=/opt/faceops -e FACEOPS_VIGIA=0 faceops python3 /tmp/p3114.py 2>&1 | grep -v -i -E "token|password|secret|clave|warn" | tail -4
echo "== después (con memo)"; sudo podman exec -w /tmp/fo3114 -e PYTHONPATH=/tmp/fo3114 -e FACEOPS_VIGIA=0 faceops python3 /tmp/p3114.py 2>&1 | grep -v -i -E "token|password|secret|clave|warn" | tail -4
sudo podman exec faceops rm -rf /tmp/p3114.py /tmp/fo3114; rm -f /tmp/cves3114.py /tmp/arq3114.py
